-- Seed analytics_snapshots (90 days) + analytics totals
SET @uid := (SELECT id FROM users WHERE email = 'david@creatorzhive.com' LIMIT 1);


VALUES (@uid, 25, 10, 7, 5, 3, 13500, 2500000, 120000, 2100000, 4.25, 0.00)
ON DUPLICATE KEY UPDATE total_posts=VALUES(total_posts), published_posts=VALUES(published_posts), draft_posts=VALUES(draft_posts), scheduled_posts=VALUES(scheduled_posts), failed_posts=VALUES(failed_posts), total_followers=VALUES(total_followers), total_impressions=VALUES(total_impressions), total_engagements=VALUES(total_engagements), total_reach=VALUES(total_reach), avg_engagement_rate=VALUES(avg_engagement_rate);
